/**
 * Async mutex for thread-safety in concurrent JavaScript environments.
 * Ensures only one async operation accesses the cache at a time.
 */
class AsyncMutex {
  constructor() {
    this._queue = [];
    this._locked = false;
  }

  async acquire() {
    if (!this._locked) {
      this._locked = true;
      return;
    }
    await new Promise((resolve) => this._queue.push(resolve));
  }

  release() {
    if (this._queue.length > 0) {
      const next = this._queue.shift();
      next();
    } else {
      this._locked = false;
    }
  }
}

/**
 * Doubly-linked list node for LRU ordering.
 */
class Node {
  constructor(key, value, expiresAt) {
    this.key = key;
    this.value = value;
    this.expiresAt = expiresAt;
    this.prev = null;
    this.next = null;
  }
}

/**
 * Thread-safe LRU cache with per-entry TTL expiration.
 *
 * - Evicts least-recently-used entries when capacity is reached.
 * - Entries expire after `ttlMs` milliseconds from insertion.
 * - All public methods are async and mutex-protected for concurrent safety.
 */
class LRUCacheWithTTL {
  /**
   * @param {number} capacity - Maximum number of entries.
   * @param {number} ttlMs - Time-to-live in milliseconds per entry.
   * @param {Function} [nowFn] - Clock function (default: Date.now). Useful for testing.
   */
  constructor(capacity, ttlMs, nowFn) {
    if (capacity <= 0) throw new Error("capacity must be > 0");
    if (ttlMs <= 0) throw new Error("ttlMs must be > 0");

    this._capacity = capacity;
    this._ttlMs = ttlMs;
    this._now = nowFn || Date.now;
    this._map = new Map();
    this._head = null; // most recently used
    this._tail = null; // least recently used
    this._mutex = new AsyncMutex();
  }

  // --- Internal doubly-linked list helpers ---

  _addToFront(node) {
    node.prev = null;
    node.next = this._head;
    if (this._head) this._head.prev = node;
    this._head = node;
    if (!this._tail) this._tail = node;
  }

  _removeNode(node) {
    if (node.prev) node.prev.next = node.next;
    else this._head = node.next;
    if (node.next) node.next.prev = node.prev;
    else this._tail = node.prev;
    node.prev = null;
    node.next = null;
  }

  _moveToFront(node) {
    this._removeNode(node);
    this._addToFront(node);
  }

  _evictLRU() {
    if (!this._tail) return;
    const old = this._tail;
    this._removeNode(old);
    this._map.delete(old.key);
  }

  _isExpired(node) {
    return this._now() >= node.expiresAt;
  }

  _purgeExpired() {
    let node = this._tail;
    while (node) {
      const prev = node.prev;
      if (this._isExpired(node)) {
        this._removeNode(node);
        this._map.delete(node.key);
      }
      node = prev;
    }
  }

  // --- Public async API (thread-safe) ---

  async get(key) {
    await this._mutex.acquire();
    try {
      const node = this._map.get(key);
      if (!node) return undefined;
      if (this._isExpired(node)) {
        this._removeNode(node);
        this._map.delete(key);
        return undefined;
      }
      this._moveToFront(node);
      return node.value;
    } finally {
      this._mutex.release();
    }
  }

  async put(key, value) {
    await this._mutex.acquire();
    try {
      const existing = this._map.get(key);
      if (existing) {
        existing.value = value;
        existing.expiresAt = this._now() + this._ttlMs;
        this._moveToFront(existing);
        return;
      }
      if (this._map.size >= this._capacity) {
        this._evictLRU();
      }
      const node = new Node(key, value, this._now() + this._ttlMs);
      this._map.set(key, node);
      this._addToFront(node);
    } finally {
      this._mutex.release();
    }
  }

  async has(key) {
    await this._mutex.acquire();
    try {
      const node = this._map.get(key);
      if (!node) return false;
      if (this._isExpired(node)) {
        this._removeNode(node);
        this._map.delete(key);
        return false;
      }
      this._moveToFront(node);
      return true;
    } finally {
      this._mutex.release();
    }
  }

  async delete(key) {
    await this._mutex.acquire();
    try {
      const node = this._map.get(key);
      if (!node) return false;
      this._removeNode(node);
      this._map.delete(key);
      return true;
    } finally {
      this._mutex.release();
    }
  }

  async size() {
    await this._mutex.acquire();
    try {
      this._purgeExpired();
      return this._map.size;
    } finally {
      this._mutex.release();
    }
  }

  async keys() {
    await this._mutex.acquire();
    try {
      this._purgeExpired();
      const result = [];
      let node = this._head;
      while (node) {
        result.push(node.key);
        node = node.next;
      }
      return result;
    } finally {
      this._mutex.release();
    }
  }
}

/**
 * Finds duplicate values in an iterable, using a thread-safe LRU cache
 * with TTL to track seen values efficiently.
 *
 * Returns an array of { value, indices, count } for each value that
 * appears more than once. The cache limits memory usage and entries
 * expire after ttlMs, so only recently-seen duplicates are detected.
 *
 * @param {Iterable} items - Values to scan for duplicates.
 * @param {Object} options
 * @param {number} [options.capacity=1000] - LRU cache capacity.
 * @param {number} [options.ttlMs=60000] - TTL in ms for cache entries.
 * @param {Function} [options.nowFn] - Clock override for testing.
 * @returns {Promise<Array<{value: *, indices: number[], count: number}>>}
 */
async function find_duplicates(items, options = {}) {
  const { capacity = 1000, ttlMs = 60000, nowFn } = options;
  const cache = new LRUCacheWithTTL(capacity, ttlMs, nowFn);

  const result = [];
  let index = 0;

  for (const item of items) {
    const key = typeof item === "object" ? JSON.stringify(item) : String(item);
    const existing = await cache.get(key);

    if (existing) {
      existing.indices.push(index);
      existing.count += 1;
      await cache.put(key, existing); // touch for LRU + refresh TTL
    } else {
      await cache.put(key, { value: item, indices: [index], count: 1 });
    }
    index++;
  }

  // Collect entries with count > 1
  const keys = await cache.keys();
  for (const key of keys) {
    const entry = await cache.get(key);
    if (entry && entry.count > 1) {
      result.push({
        value: entry.value,
        indices: entry.indices,
        count: entry.count,
      });
    }
  }

  return result;
}

