  const cache = new LRUCacheWithTTL(100, 10000);
  const log = [];

  // Two async operations that interleave without a mutex
  async function op1() {
    await cache.put("shared", 0);
    // Simulate async work
    await new Promise((r) => setTimeout(r, 10));
    const val = await cache.get("shared");
    log.push({ op: "op1", val });
    await cache.put("shared", val + 10);
  }

  async function op2() {
    await new Promise((r) => setTimeout(r, 5));
    const val = await cache.get("shared");
    log.push({ op: "op2", val });
    await cache.put("shared", val + 100);
  }

  await Promise.all([op1(), op2()]);

  const final = await cache.get("shared");
  // With mutex: op1 runs first (sets 0, reads 0, writes 10), then op2 (reads 10, writes 110)
  // Without mutex: op2 might read 0 and both write 10/100, losing one update
  assertDeepEqual(final, 110, "mutex ensures sequential access: final value is 110");
  assertDeepEqual(
    log,
    [
      { op: "op1", val: 0 },
      { op: "op2", val: 10 },
    ],
    "operations executed in correct order"
  );
}

